from collections import deque
import heapq


def topological_sort(graph):
    """Order the nodes so every node comes before the nodes it points to.

    Nodes may appear only as targets (without their own key). When several nodes are
    available at the same time, take them in alphabetical order. Raise ValueError if the
    graph contains a cycle.
    """
    # Determine the full set of nodes (keys and any targets)
    nodes = set(graph.keys())
    for targets in graph.values():
        nodes.update(targets)

    # Initialise indegree counts for all nodes
    indegree = {node: 0 for node in nodes}
    for src, targets in graph.items():
        for t in targets:
            indegree[t] += 1

    # Use a min‑heap to always pop the alphabetically smallest ready node
    ready = [node for node, deg in indegree.items() if deg == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for target in graph.get(node, []):
            indegree[target] -= 1
            if indegree[target] == 0:
                heapq.heappush(ready, target)

    if len(order) != len(nodes):
        # Cycle detected – not all nodes could be ordered
        raise ValueError("graph contains a cycle")
    return order


def shortest_path(graph, start, goal):
    """Return the shortest path from start to goal as a list of nodes, including both ends.

    Returns [start] when start == goal, and None when goal cannot be reached.
    """
    queue = deque([start])
    parent = {start: None}
    while queue:
        node = queue.popleft()
        if node == goal:
            break
        for neighbour in graph.get(node, []):
            if neighbour not in parent:
                parent[neighbour] = node
                queue.append(neighbour)

    if goal not in parent:
        return None
    # Reconstruct path backwards then reverse to obtain forward order
    path = []
    node = goal
    while node is not None:
        path.append(node)
        node = parent[node]
    return list(reversed(path))
